#!/usr/bin/env python3
"""Test borgbackup package: verify .so extensions and Python source files exist."""
import sys
import os
import glob

def main():
    # Read site-packages path from pkg_path.txt (generated by conanfile generate())
    script_dir = os.path.dirname(os.path.abspath(__file__))
    pkg_path_file = os.path.join(script_dir, "pkg_path.txt")

    site_packages = ""
    if os.path.exists(pkg_path_file):
        with open(pkg_path_file) as f:
            site_packages = f.read().strip()

    if not site_packages:
        site_packages = os.environ.get("PYTHONPATH", "")

    if site_packages:
        sys.path.insert(0, site_packages)

    expected_sos = [
        "borg/chunker", "borg/compress", "borg/hashindex", "borg/item",
        "borg/algorithms/checksums", "borg/crypto/low_level",
        "borg/platform/posix", "borg/platform/linux", "borg/platform/syncfilerange",
    ]

    failed = []

    # Check .so files exist
    so_files = glob.glob(os.path.join(site_packages, "borg", "**", "*.so"), recursive=True)
    print(f"Found {len(so_files)} .so files")

    for ext in expected_sos:
        pattern = os.path.join(site_packages, ext + "*.so")
        if glob.glob(pattern):
            print(f"OK: {ext}")
        else:
            print(f"FAIL: {ext} not found")
            failed.append(ext)

    # Check key Python source files exist
    py_checks = [
        "borg/__init__.py",
        "borg/archiver.py",
        "borg/helpers/__init__.py",
    ]
    for pyfile in py_checks:
        path = os.path.join(site_packages, pyfile)
        if os.path.exists(path):
            print(f"OK: {pyfile}")
        else:
            print(f"FAIL: {pyfile} not found")
            failed.append(pyfile)

    if failed:
        print(f"FAILED: {failed}")
        sys.exit(1)
    else:
        print("All checks passed - 9 .so extensions + Python sources verified")

if __name__ == "__main__":
    main()
